cat > /app/output/styles.css << 'EOF'
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700;800&family=Inter:wght@400;500;600&display=swap');

:root {
  --bg: #f5f2ed;
  --bg-soft: #eee8df;
  --text: #1a1a1a;
  --muted: #5f5a54;
  --line: #d8d1c7;
  --accent-1: #c68f78;
  --accent-2: #9cae92;
  --accent-3: #d9bf98;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;
  --radius: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, sans-serif;
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }

.site-wrap {
  min-height: 100vh;
  padding: 0 5vw 4rem;
}

.container {
  width: min(1220px, 100%);
  margin: 0 auto;
}

.header {
  padding: 1.4rem 0;
  position: sticky;
  top: 0;
  z-index: 20;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  backdrop-filter: blur(6px);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
}

.nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.brand {
  font-family: 'Playfair Display', Georgia, serif;
  font-weight: 700;
  font-size: clamp(1.2rem, 2vw, 1.6rem);
  letter-spacing: 0.01em;
}

.brand-tag {
  font-size: 0.72rem;
  color: var(--muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-left: 0.55rem;
}

.nav-links {
  display: flex;
  gap: 1.35rem;
  align-items: center;
  font-size: 0.95rem;
}

.nav-links a {
  position: relative;
  padding-bottom: 0.12rem;
}

.nav-links a::after {
  content: '';
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: var(--text);
  transition: right 220ms ease;
}

.nav-links a:hover::after,
.nav-links a.active::after { right: 0; }

.menu-btn {
  display: none;
  border: 0;
  background: transparent;
  font-size: 1.55rem;
  color: var(--text);
  cursor: pointer;
  min-width: 44px;
  min-height: 44px;
}

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: color-mix(in srgb, var(--bg) 96%, #bca98f 4%);
  z-index: 50;
  display: none;
  padding: 2rem 8vw;
}

.mobile-overlay.open { display: block; }

.mobile-overlay nav {
  margin-top: 4.5rem;
  display: grid;
  gap: 1.25rem;
}

.mobile-overlay a {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.8rem, 7vw, 3rem);
  line-height: 1.1;
}

h1, h2, h3, h4 {
  font-family: 'Playfair Display', Georgia, serif;
  line-height: 1.1;
  margin: 0;
}

.hero {
  padding: clamp(4rem, 12vh, 8rem) 0 3.5rem;
  display: grid;
  gap: 1.25rem;
  max-width: 900px;
}

.hero h1 {
  font-size: clamp(2.35rem, 8vw, 6.1rem);
  letter-spacing: -0.02em;
}

.lead {
  max-width: 60ch;
  color: var(--muted);
  font-size: clamp(1rem, 1.4vw, 1.18rem);
}

.media-grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 1rem;
  margin: 3rem 0 5rem;
}

.media-block {
  border-radius: var(--radius);
  min-height: 150px;
}

.marquee-section { margin: 3rem 0 5rem; }
.marquee-row {
  overflow: hidden;
  border-top: 1px solid var(--line);
  padding: 0.8rem 0;
}
.marquee-row:last-child { border-bottom: 1px solid var(--line); }

.marquee-track {
  display: flex;
  width: max-content;
  gap: 2.2rem;
  align-items: center;
  will-change: transform;
  animation: scroll-left 24s linear infinite;
}

.marquee-row.reverse .marquee-track { animation-name: scroll-right; }
.marquee-row.slow .marquee-track { animation-duration: 30s; }

.marquee-item {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.1rem, 2vw, 1.5rem);
  white-space: nowrap;
}

@keyframes scroll-left {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

@keyframes scroll-right {
  from { transform: translateX(-50%); }
  to { transform: translateX(0); }
}

.section { margin: 4rem 0; }

.about {
  max-width: 75ch;
  color: var(--muted);
  font-size: 1.03rem;
}

.longform {
  max-width: 760px;
  margin: clamp(3rem, 8vh, 6rem) auto;
}

.longform h1 {
  font-size: clamp(2.2rem, 7vw, 4.8rem);
  margin-bottom: 1.25rem;
}

.longform .intro {
  font-size: 1.18rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

.longform p {
  margin: 0 0 1.25rem;
  font-size: 1.08rem;
}

.divider {
  border: 0;
  border-top: 1px solid var(--line);
  margin: 3rem 0;
}

.services-grid,
.clients-grid {
  display: grid;
  gap: 1.4rem;
}

.services-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.clients-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }

.card {
  padding: 1.2rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg) 96%, #fff 4%);
}

.card h3 {
  margin-bottom: 0.4rem;
  font-size: 1.6rem;
}

.card p { margin: 0; color: var(--muted); }

.contact-hero {
  min-height: 68vh;
  display: grid;
  align-content: center;
  justify-items: center;
  text-align: center;
}

.contact-hero h1 {
  font-size: clamp(4rem, 18vw, 14rem);
  letter-spacing: -0.03em;
  line-height: 0.92;
}

.contact-links {
  display: flex;
  gap: 1.6rem;
  justify-content: center;
  font-size: clamp(1rem, 2vw, 1.3rem);
}

@media (max-width: 980px) {
  .services-grid, .clients-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .site-wrap { padding: 0 6vw 3rem; }
  .nav-links { display: none; }
  .menu-btn { display: inline-flex; align-items: center; justify-content: center; }
  .services-grid, .clients-grid { grid-template-columns: 1fr; }
  .media-grid { grid-template-columns: 1fr 1fr; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const menuBtn = document.querySelector('[data-menu-btn]');
  const overlay = document.querySelector('[data-mobile-overlay]');

  if (menuBtn && overlay) {
    menuBtn.addEventListener('click', function () {
      const isOpen = overlay.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', String(isOpen));
      menuBtn.textContent = isOpen ? '×' : '☰';
    });

    overlay.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        overlay.classList.remove('open');
        menuBtn.setAttribute('aria-expanded', 'false');
        menuBtn.textContent = '☰';
      });
    });
  }
})();
EOF

